    --clr-accent-hover: #334155;

    --clr-danger: #ef4444;
    --clr-danger-bg: #fef2f2;
    --clr-success: #10b981;

    /* Typography */
    --ff-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

    /* Spacing */
    --space-1: 0.25rem;
    --space-2: 0.5rem;
    --space-3: 0.75rem;
    --space-4: 1rem;
    --space-6: 1.5rem;
    --space-8: 2rem;
    --space-12: 3rem;
    --space-16: 4rem;
    --space-24: 6rem;

    /* Border Radius */
    --br-sm: 0.25rem;
    --br-md: 0.5rem;
    --br-lg: 1rem;
    --br-full: 9999px;

    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);

    /* Layout */
    --container-max-width: 1280px;
    --header-height: 4.5rem;
}

/* Reset */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--ff-sans);
    color: var(--clr-primary-900);
    background-color: var(--clr-white);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

img, picture, video, canvas, svg {
    display: block;
    max-width: 100%;
}

input, button, textarea, select {
    font: inherit;
}

button {
    cursor: pointer;
    border: none;
    background: none;
}

a {
    color: inherit;
    text-decoration: none;
}

ul {
    list-style: none;
}

/* Typography base */
h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.2;
    color: var(--clr-primary-900);
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.75rem 1.5rem;
    font-weight: 500;
    border-radius: var(--br-full);
    transition: all 0.2s ease;
    text-align: center;
}

.btn-primary {
    background-color: var(--clr-accent);
    color: var(--clr-white);
}

.btn-primary:hover {
    background-color: var(--clr-accent-hover);
    transform: translateY(-2px);
}

.btn-secondary {
    background-color: var(--clr-white);
    color: var(--clr-primary-900);
    border: 1px solid var(--clr-primary-200);
}

.btn-secondary:hover {
    background-color: var(--clr-primary-50);
    border-color: var(--clr-primary-500);
}

/* Header */
.header {
    height: var(--header-height);
    border-bottom: 1px solid var(--clr-primary-100);
    position: sticky;
    top: 0;
    background-color: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(8px);
    z-index: 100;
}

.header-container {
    max-width: var(--container-max-width);
    margin: 0 auto;
    padding: 0 var(--space-4);
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.mobile-menu-toggle {
    display: none;
    font-size: 1.5rem;
    color: var(--clr-primary-900);
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: -0.025em;
}

.main-nav {
    display: flex;
}

.nav-list {
    display: flex;
    gap: var(--space-8);
}

.nav-link {
    font-size: 0.95rem;
    font-weight: 500;
    color: var(--clr-primary-800);
    transition: color 0.2s;
}

.nav-link:hover {
    color: var(--clr-primary-900);
}

.sale-link {
    color: var(--clr-danger);
}

.sale-link:hover {
    color: #b91c1c;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--space-4);
}

.icon-btn {
    font-size: 1.25rem;
    color: var(--clr-primary-800);
    transition: color 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
}

.icon-btn:hover {
    color: var(--clr-primary-900);
}

.cart-btn {
    position: relative;
}

.cart-count {
    position: absolute;
    top: -5px;
    right: -8px;
    background-color: var(--clr-accent);
    color: var(--clr-white);
    font-size: 0.65rem;
    font-weight: 600;
    height: 16px;
    min-width: 16px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0 4px;
}

/* Sections */
.section {
    padding: var(--space-16) var(--space-4);
    max-width: var(--container-max-width);
    margin: 0 auto;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--space-8);
}

.section-title {
    font-size: 2rem;
    letter-spacing: -0.025em;
}

.view-all {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    font-weight: 500;
    color: var(--clr-primary-800);
    transition: gap 0.2s;
}

.view-all:hover {
    gap: var(--space-3);
}

/* Hero */
.hero {
    max-width: var(--container-max-width);
    margin: var(--space-6) auto;
    padding: 0 var(--space-4);
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-12);
    align-items: center;
    min-height: calc(85vh - var(--header-height));
}

.hero-content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.hero-subtitle {
    font-size: 0.875rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--clr-primary-500);
    margin-bottom: var(--space-4);
}

.hero-title {
    font-size: clamp(2.5rem, 5vw, 4rem);
    line-height: 1.1;
    margin-bottom: var(--space-6);
}

.hero-description {
    font-size: 1.125rem;
    color: var(--clr-primary-500);
    margin-bottom: var(--space-8);
    max-width: 480px;
}

.hero-actions {
    display: flex;
    gap: var(--space-4);
}

.hero-image-container {
    height: 100%;
    width: 100%;
    border-radius: var(--br-lg);
    overflow: hidden;
    box-shadow: var(--shadow-lg);
}

.hero-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
}

/* Product Cards */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--space-8) var(--space-6);
}

.product-card {
    display: flex;
    flex-direction: column;
}

.product-image-wrapper {
    position: relative;
    aspect-ratio: 3/4;
    border-radius: var(--br-md);
    overflow: hidden;
    background-color: var(--clr-primary-50);
    margin-bottom: var(--space-4);
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.btn-wishlist {
    position: absolute;
    top: var(--space-3);
    right: var(--space-3);
    width: 36px;
    height: 36px;
    background-color: var(--clr-white);
    border-radius: var(--br-full);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.25rem;
    color: var(--clr-primary-800);
    box-shadow: var(--shadow-sm);
    transition: all 0.2s;
    opacity: 0;
    transform: translateY(-10px);
}

.product-card:hover .btn-wishlist {
    opacity: 1;
    transform: translateY(0);
}

.btn-wishlist:hover {
    color: var(--clr-danger);
    transform: scale(1.1) !important;
}

.product-badges {
    position: absolute;
    top: var(--space-3);
    left: var(--space-3);
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
}

.badge {
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 600;
    border-radius: var(--br-full);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.badge-new {
    background-color: var(--clr-white);
    color: var(--clr-primary-900);
}

.badge-sale {
    background-color: var(--clr-danger);
    color: var(--clr-white);
}

.product-info {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-name {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: var(--space-1);
}

.product-category {
    font-size: 0.875rem;
    color: var(--clr-primary-500);
    margin-bottom: var(--space-3);
}

.product-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: auto;
}

.product-price {
    font-weight: 600;
    font-size: 1.125rem;
}

.price-wrap {
    display: flex;
    align-items: center;
    gap: var(--space-2);
}

.price-original {
    color: var(--clr-primary-500);
    text-decoration: line-through;
    font-size: 0.875rem;
    font-weight: 400;
}

.price-sale {
    color: var(--clr-danger);
}

.btn-add-cart {
    font-size: 0.875rem;
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 4px;
    color: var(--clr-primary-800);
    transition: color 0.2s;
}

.btn-add-cart:hover {
    color: var(--clr-accent);
}

/* Deals Section */
.deals {
    background-color: var(--clr-primary-50);
    border-radius: var(--br-lg);
    margin-top: var(--space-12);
    margin-bottom: var(--space-12);
}

.deals-container {
    display: grid;
    grid-template-columns: 1fr 1.5fr;
    gap: var(--space-12);
    align-items: center;
}

.deals-content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.deals-tag {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background-color: var(--clr-danger-bg);
    color: var(--clr-danger);
    font-size: 0.875rem;
    font-weight: 600;
    border-radius: var(--br-full);
    margin-bottom: var(--space-4);
}

.deals-title {
    font-size: 2.5rem;
    margin-bottom: var(--space-4);
}

.deals-desc {
    color: var(--clr-primary-500);
    margin-bottom: var(--space-6);
    font-size: 1.125rem;
}

.countdown {
    display: flex;
    gap: var(--space-4);
    margin-bottom: var(--space-8);
}

.time-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: var(--clr-white);
    padding: var(--space-3) var(--space-4);
    border-radius: var(--br-md);
    min-width: 80px;
    box-shadow: var(--shadow-sm);
}

.time-value {
    font-size: 1.5rem;
    font-weight: 700;
    line-height: 1;
    margin-bottom: var(--space-1);
}

.time-label {
    font-size: 0.75rem;
    color: var(--clr-primary-500);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.deals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-6);
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: var(--space-8);
}

.editorial-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-4);
}

.editorial-image-wrapper {
    aspect-ratio: 16/10;
    border-radius: var(--br-md);
    overflow: hidden;
}

.editorial-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.editorial-card:hover .editorial-image {
