}

.editorial-category {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--clr-primary-500);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.editorial-title {
    font-size: 1.5rem;
    margin-bottom: var(--space-2);
}

.editorial-excerpt {
    color: var(--clr-primary-500);
    margin-bottom: var(--space-4);
}

.editorial-link {
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 4px;
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    transition: gap 0.2s;
}

.editorial-link:hover {
    gap: var(--space-3);
}

/* Footer */
.footer {
    background-color: var(--clr-primary-900);
    color: var(--clr-white);
    padding: var(--space-16) var(--space-4) var(--space-8);
    margin-top: var(--space-16);
}

.footer-top {
    max-width: var(--container-max-width);
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: var(--space-12);
    margin-bottom: var(--space-12);
}

.footer-brand .logo {
    display: block;
    margin-bottom: var(--space-4);
}

.footer-desc {
    color: var(--clr-primary-200);
    margin-bottom: var(--space-6);
    max-width: 300px;
}

.social-links {
    display: flex;
    gap: var(--space-4);
}

.social-links a {
    font-size: 1.5rem;
    color: var(--clr-white);
    opacity: 0.8;
    transition: opacity 0.2s;
}

.social-links a:hover {
    opacity: 1;
}

.footer-heading {
    font-size: 1.125rem;
    margin-bottom: var(--space-6);
    color: var(--clr-white);
}

.footer-links ul {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.footer-links a {
    color: var(--clr-primary-200);
    opacity: 0.8;
    transition: opacity 0.2s;
}

.footer-links a:hover {
    opacity: 1;
}

.footer-newsletter p {
    color: var(--clr-primary-200);
    margin-bottom: var(--space-4);
    opacity: 0.8;
}

.newsletter-form {
    display: flex;
    gap: var(--space-2);
}

.newsletter-form input {
    flex-grow: 1;
    padding: 0.75rem 1rem;
    border-radius: var(--br-md);
    border: none;
    outline: none;
}

.newsletter-form .btn {
    border-radius: var(--br-md);
}

.footer-bottom {
    max-width: var(--container-max-width);
    margin: 0 auto;
    padding-top: var(--space-8);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    display: flex;
    justify-content: space-between;
