        left: 0;
        right: 0;
        background-color: var(--clr-white);
        padding: var(--space-4);
        box-shadow: var(--shadow-md);
        border-top: 1px solid var(--clr-primary-100);
    }

    .main-nav.active {
        display: block;
    }

    .nav-list {
        flex-direction: column;
        gap: var(--space-4);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .footer-top {
        grid-template-columns: 1fr;
    }

    .footer-bottom {
        flex-direction: column;
        gap: var(--space-4);
        text-align: center;
    }

    .newsletter-form {
        flex-direction: column;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    // --- Mobile Menu Toggle ---
    const menuToggle = document.querySelector('.mobile-menu-toggle');
    const mainNav = document.querySelector('.main-nav');

    if (menuToggle && mainNav) {
        menuToggle.addEventListener('click', () => {
            mainNav.classList.toggle('active');
            const icon = menuToggle.querySelector('i');
            if (mainNav.classList.contains('active')) {
                icon.classList.remove('ph-list');
                icon.classList.add('ph-x');
            } else {
                icon.classList.remove('ph-x');
                icon.classList.add('ph-list');
            }
        });
    }

    // --- Add to Cart Functionality ---
    const addToCartBtns = document.querySelectorAll('.btn-add-cart');
    const cartCountEl = document.querySelector('.cart-count');
    const toastContainer = document.getElementById('toast-container');
    let cartCount = 0;

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault(); // Prevent jump to top if it's an anchor

            // Update cart count
            cartCount++;
            cartCountEl.textContent = cartCount;

            // Animate cart badge
            cartCountEl.style.transform = 'scale(1.3)';
            setTimeout(() => {
                cartCountEl.style.transform = 'scale(1)';
            }, 200);

            // Get product name
            const productCard = this.closest('.product-card');
            const productName = productCard.querySelector('.product-name').textContent;

            // Show toast notification
            showToast(`Added ${productName} to cart`);
        });
    });

    function showToast(message) {
        const toast = document.createElement('div');
        toast.className = 'toast';
        toast.innerHTML = `
            <i class="ph ph-check-circle toast-icon"></i>
            <span>${message}</span>
        `;

        toastContainer.appendChild(toast);

        // Trigger reflow for animation
        toast.offsetHeight;

        // Show
        toast.classList.add('show');

        // Hide and remove after 3 seconds
        setTimeout(() => {
            toast.classList.remove('show');
            setTimeout(() => {
                toast.remove();
            }, 300); // Wait for transition to finish
        }, 3000);
    }

    // --- Deals Countdown Timer ---
    // A simple mock countdown for visual effect
    const timeBlocks = document.querySelectorAll('.time-value');
    if (timeBlocks.length === 3) {
        let days = parseInt(timeBlocks[0].textContent);
        let hours = parseInt(timeBlocks[1].textContent);
        let mins = parseInt(timeBlocks[2].textContent);

        setInterval(() => {
            mins--;
            if (mins < 0) {
                mins = 59;
                hours--;
                if (hours < 0) {
                    hours = 23;
                    days--;
                    if (days < 0) days = 0; // Stop at 0
                }
            }

            timeBlocks[0].textContent = days.toString().padStart(2, '0');
            timeBlocks[1].textContent = hours.toString().padStart(2, '0');
            timeBlocks[2].textContent = mins.toString().padStart(2, '0');
        }, 60000); // Update every minute
    }
});

