    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--space-8) var(--space-6);
}

.product-card {
    display: flex;
    flex-direction: column;
}

.product-image-wrapper {
    position: relative;
    aspect-ratio: 3/4;
    border-radius: var(--br-md);
    overflow: hidden;
    background-color: var(--clr-primary-50);
    margin-bottom: var(--space-4);
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.btn-wishlist {
    position: absolute;
    top: var(--space-3);
    right: var(--space-3);
    width: 36px;
    height: 36px;
    background-color: var(--clr-white);
    border-radius: var(--br-full);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.25rem;
    color: var(--clr-primary-800);
    box-shadow: var(--shadow-sm);
    transition: all 0.2s;
    opacity: 0;
    transform: translateY(-10px);
}

.product-card:hover .btn-wishlist {
    opacity: 1;
    transform: translateY(0);
}

.btn-wishlist:hover {
    color: var(--clr-danger);
    transform: scale(1.1) !important;
}

.product-badges {
    position: absolute;
    top: var(--space-3);
    left: var(--space-3);
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
}

.badge {
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 600;
    border-radius: var(--br-full);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.badge-new {
    background-color: var(--clr-white);
    color: var(--clr-primary-900);
}

.badge-sale {
    background-color: var(--clr-danger);
    color: var(--clr-white);
}

.product-info {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-name {
    font-size: 1rem;
    font-weight: 500;
    margin-bottom: var(--space-1);
}

.product-category {
    font-size: 0.875rem;
    color: var(--clr-primary-500);
    margin-bottom: var(--space-3);
}

.product-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: auto;
}

.product-price {
    font-weight: 600;
    font-size: 1.125rem;
}

.price-wrap {
    display: flex;
    align-items: center;
    gap: var(--space-2);
}

.price-original {
    color: var(--clr-primary-500);
    text-decoration: line-through;
    font-size: 0.875rem;
    font-weight: 400;
}

.price-sale {
    color: var(--clr-danger);
}

.btn-add-cart {
    font-size: 0.875rem;
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 4px;
    color: var(--clr-primary-800);
    transition: color 0.2s;
}

.btn-add-cart:hover {
    color: var(--clr-accent);
}

/* Deals Section */
.deals {
    background-color: var(--clr-primary-50);
    border-radius: var(--br-lg);
    margin-top: var(--space-12);
    margin-bottom: var(--space-12);
}

.deals-container {
    display: grid;
    grid-template-columns: 1fr 1.5fr;
    gap: var(--space-12);
    align-items: center;
}

.deals-content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.deals-tag {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background-color: var(--clr-danger-bg);
    color: var(--clr-danger);
    font-size: 0.875rem;
    font-weight: 600;
    border-radius: var(--br-full);
    margin-bottom: var(--space-4);
}

.deals-title {
    font-size: 2.5rem;
    margin-bottom: var(--space-4);
}

.deals-desc {
    color: var(--clr-primary-500);
    margin-bottom: var(--space-6);
    font-size: 1.125rem;
}

.countdown {
    display: flex;
    gap: var(--space-4);
    margin-bottom: var(--space-8);
}

.time-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: var(--clr-white);
    padding: var(--space-3) var(--space-4);
    border-radius: var(--br-md);
    min-width: 80px;
    box-shadow: var(--shadow-sm);
}

.time-value {
    font-size: 1.5rem;
    font-weight: 700;
    line-height: 1;
    margin-bottom: var(--space-1);
}

.time-label {
    font-size: 0.75rem;
    color: var(--clr-primary-500);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.deals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-6);
}

/* Editorial Section */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: var(--space-8);
}

.editorial-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-4);
}

.editorial-image-wrapper {
    aspect-ratio: 16/10;
    border-radius: var(--br-md);
    overflow: hidden;
}

.editorial-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.editorial-card:hover .editorial-image {
    transform: scale(1.05);
}

.editorial-category {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--clr-primary-500);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.editorial-title {
    font-size: 1.5rem;
    margin-bottom: var(--space-2);
}

.editorial-excerpt {
    color: var(--clr-primary-500);
    margin-bottom: var(--space-4);
}

.editorial-link {
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 4px;
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    transition: gap 0.2s;
}

.editorial-link:hover {
    gap: var(--space-3);
}

/* Footer */
.footer {
    background-color: var(--clr-primary-900);
    color: var(--clr-white);
    padding: var(--space-16) var(--space-4) var(--space-8);
    margin-top: var(--space-16);
}

.footer-top {
    max-width: var(--container-max-width);
    margin: 0 auto;
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: var(--space-12);
    margin-bottom: var(--space-12);
}

.footer-brand .logo {
    display: block;
    margin-bottom: var(--space-4);
}

.footer-desc {
    color: var(--clr-primary-200);
    margin-bottom: var(--space-6);
    max-width: 300px;
}

.social-links {
    display: flex;
    gap: var(--space-4);
}

.social-links a {
    font-size: 1.5rem;
    color: var(--clr-white);
    opacity: 0.8;
    transition: opacity 0.2s;
}

.social-links a:hover {
    opacity: 1;
}

.footer-heading {
    font-size: 1.125rem;
    margin-bottom: var(--space-6);
    color: var(--clr-white);
}

.footer-links ul {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
}

.footer-links a {
    color: var(--clr-primary-200);
    opacity: 0.8;
    transition: opacity 0.2s;
}

.footer-links a:hover {
    opacity: 1;
}

.footer-newsletter p {
    color: var(--clr-primary-200);
    margin-bottom: var(--space-4);
    opacity: 0.8;
}

.newsletter-form {
    display: flex;
    gap: var(--space-2);
}

.newsletter-form input {
    flex-grow: 1;
    padding: 0.75rem 1rem;
    border-radius: var(--br-md);
    border: none;
    outline: none;
}

.newsletter-form .btn {
    border-radius: var(--br-md);
}

.footer-bottom {
    max-width: var(--container-max-width);
    margin: 0 auto;
    padding-top: var(--space-8);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: var(--clr-primary-200);
    opacity: 0.8;
    font-size: 0.875rem;
}

.footer-legal {
    display: flex;
    gap: var(--space-6);
}

/* Toast Notification */
.toast-container {
    position: fixed;
    bottom: var(--space-6);
    right: var(--space-6);
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
    z-index: 1000;
}

.toast {
    background-color: var(--clr-primary-900);
    color: var(--clr-white);
    padding: 1rem 1.5rem;
    border-radius: var(--br-md);
    box-shadow: var(--shadow-lg);
    display: flex;
    align-items: center;
